{
  "candidate_rtl": "module comparator_16bit (
    input [15:0] A,
    input [15:0] B,
    output gt,
    output eq,
    output lt
);
    wire [15:0] same;
    wire [15:0] greater_bit;
    wire [3:0] group_eq;
    wire [3:0] group_gt;
    wire [3:0] group_lt;

    assign same = ~(A ^ B);
    assign greater_bit = A & ~B;

    genvar k;
    generate
        for (k = 0; k < 4; k = k + 1) begin : groups
            assign group_eq[k] = &same[4*k +: 4];
            assign group_gt[k] =
                greater_bit[4*k+3] |
                (same[4*k+3] & greater_bit[4*k+2]) |
                (same[4*k+3] & same[4*k+2] & greater_bit[4*k+1]) |
                (same[4*k+3] & same[4*k+2] & same[4*k+1] & greater_bit[4*k]);
            assign group_lt[k] = ~(group_gt[k] | group_eq[k]);
        end
    endgenerate

    assign eq = &group_eq;
    assign gt = group_gt[3] |
                (group_eq[3] & group_gt[2]) |
                (group_eq[3] & group_eq[2] & group_gt[1]) |
                (group_eq[3] & group_eq[2] & group_eq[1] & group_gt[0]);
    assign lt = group_lt[3] |
                (group_eq[3] & group_lt[2]) |
                (group_eq[3] & group_eq[2] & group_lt[1]) |
                (group_eq[3] & group_eq[2] & group_eq[1] & group_lt[0]);
endmodule
",
  "bottleneck": "The baseline has reconvergent comparison logic and a relatively deep low-order-input path to gt. Equality also shares a late-arriving portion of that mapped network.",
  "rewrite": "Use four parallel unsigned four-bit comparison groups, followed by explicit four-way lookahead selection. Share bit equality and group equality. Obtain each group's less-than result from the complement of its greater-than-or-equal result, avoiding a second complete local comparison network.",
  "expected_timing_gain": "The bounded local comparison depth and parallel group lookahead are intended to improve on the 0.88 ns baseline. Actual improvement requires mapping and STA; no measured timing or electrical-rule result is claimed.",
  "area_or_other_cost": "Shared equality and complementary local less-than generation limit duplication. Lookahead introduces additional product terms and equality fanout. Mapped area must be checked against 547.775360 um2, and zero slew and capacitance violations must be verified in the specified flow.",
  "functional_boundaries": "Preserves the module name and all unsigned 16-bit input and scalar output ports. For every binary A and B, eq indicates equality, gt indicates unsigned A > B, and lt indicates unsigned A < B. There are no parameters, state, latency, assumptions, external dependencies, or undefined outputs."
}
